"""Developer curriculum: original IDs retained, deeper material added without resetting progress."""
DOC='https://docs.openssl.org/3.5/'
def api(name,args,ownership,returns,failure):
    return dict(name=name,args=args,ownership=ownership,returns=returns,failure=failure)
def section(title,*paragraphs):return dict(title=title,paragraphs=list(paragraphs))
def step(title,text,command,expect):return dict(title=title,text=text,command=command,expect=expect)
def build(name,args=''):return f'cd ~/lab\nstudy-build examples/cpp/{name}.cpp {args}'.rstrip()

NEW=[]
def add(id,module,title,minutes,intro,concepts,sections,apis,steps,quiz,docs,file,challenge):
    NEW.append(dict(id=id,module=module,title=title,minutes=minutes,intro=intro,concepts=concepts,sections=sections,apis=apis,steps=steps,
      quiz=dict(question=quiz[0],options=quiz[1],answer=quiz[2],explanation=quiz[3]),docs=[d if d.startswith('http') else DOC+d for d in docs],
      file=f'examples/cpp/{file}.cpp' if file else None,challenge=challenge))

add('basic-bytes',1,'출발점: 바이트와 암호 도구의 역할',25,
 '암호학을 처음 배우는 C++ 개발자를 위한 출발점입니다. 계산의 입력은 문자열의 의미가 아니라 정확한 바이트 배열입니다. 이번 레슨은 암호 알고리즘보다 입력과 출력의 표현을 먼저 다룹니다.',
 ['암호화는 비밀키가 있는 쪽만 내용을 읽도록 합니다. 해시는 입력을 고정 길이 값으로 요약합니다. MAC과 서명은 변조 검증에 사용하지만 키를 공유하는 방식이 다릅니다.',
  'hex와 Base64는 인코딩입니다. 키 없이 되돌릴 수 있으므로 비밀성을 제공하지 않습니다.',
  '키 교환은 공유 비밀을 만드는 과정입니다. 인증 없이 키 교환만 하면 상대가 누구인지는 알 수 없습니다.'],
 [section('A, NUL, B는 몇 바이트인가?', 'C 문자열 API는 NUL을 종료 표시로 사용하지만 바이너리 데이터에서 0x00은 정상적인 데이터입니다. std::string도 길이를 따로 갖기 때문에 중간 NUL을 담을 수 있습니다. 네트워크 데이터에 strlen을 적용하면 입력이 잘립니다.',
   '예제의 배열은 41 00 42 세 바이트입니다. strlen은 첫 NUL까지만 세어 1을 반환합니다. EVP API에는 data 포인터와 size를 함께 전달해야 합니다. hex 문자열 410042는 여섯 문자이며 원래 세 바이트와 서로 다른 입력입니다.'),
  section('기능을 문제와 연결하기','비밀번호 저장, 파일 전송, 서버 인증은 요구가 다릅니다. SHA-256만 계산하면 공격자가 파일과 해시를 함께 바꿀 수 있습니다. HMAC은 비밀키를 아는 상대의 무결성 검증, 서명은 공개키를 가진 검증자에게 검증 가능성을 제공합니다.','이 과정은 암호 알고리즘을 직접 구현하는 과정이 아닙니다. 알고리즘의 역할을 이해하고 검증된 OpenSSL 구현을 정확한 인자와 수명 규칙으로 사용하는 연습입니다.')],
 [api('EVP_DigestUpdate(ctx, data, count)','data: 읽을 바이트 시작 주소. count: 바이트 수(size_t).','입력 메모리는 호출 동안 유효해야 합니다. 소유권을 넘기지 않습니다.','1 성공, 0 실패.','문자 수와 바이트 수를 혼동하거나 strlen으로 바이너리 길이를 계산하면 다른 데이터의 해시를 얻습니다.')],
 [step('바이트 관찰','공통 헤더 study.hpp는 RAII와 출력 도우미입니다. 우선 digest.cpp의 bytes 분기만 읽습니다.',build('digest','bytes'),'bytes=3 hex=410042 strlen=1'),
  step('인코딩 왕복','Base64 결과는 암호문이 아닙니다. 두 번째 명령이 원문을 복원합니다.','printf hello | openssl base64\nprintf aGVsbG8= | openssl base64 -d -A','aGVsbG8= / hello')],
 ('410042라는 hex 문자열과 0x41 0x00 0x42 배열은 같은 입력인가요?',['예','아니요, 인코딩을 해제해야 같은 바이트가 됩니다'],1,'표현과 실제 바이트를 구분하세요. 암호 API는 화면에 보이는 의미를 해석하지 않습니다.'),
 ['man3/EVP_DigestInit/','man1/openssl-enc/'],'digest','배열에 0xFF를 추가하고 size, hex, strlen을 각각 예측한 뒤 실행해 보세요.')

add('basic-hash',1,'해시: 결정성·개행·스트리밍',30,
 'SHA-256을 이용해 입력 길이와 Update 호출 횟수가 결과에 어떤 영향을 주는지 실험합니다. 해시 함수가 제공하지 않는 보장도 함께 구분합니다.',
 ['동일한 바이트는 동일한 해시를 만듭니다. 해시 출력은 암호화된 원문이 아니므로 복호화 API가 없습니다.',
  '충돌 저항성은 충돌이 존재하지 않는다는 뜻이 아니라 충돌 쌍을 찾기 어렵다는 성질입니다.',
  '암호학적 해시와 비밀번호 해싱은 같은 설계 문제가 아닙니다. 빠른 SHA-256 단독 사용은 비밀번호 저장용 KDF를 대체하지 않습니다.'],
 [section('상태를 가진 계산','EVP_MD는 SHA-256이라는 알고리즘 구현을 나타내고 EVP_MD_CTX는 이번 계산의 상태를 담습니다. 동일 구현으로 독립적인 메시지들을 처리하려면 계산 컨텍스트를 분리하거나 올바르게 다시 초기화해야 합니다.',
  'Init 뒤 Update를 여러 번 호출하면 입력이 순서대로 이어집니다. Update("a") + Update("bc")는 Update("abc")와 같습니다. Final 뒤 새 메시지를 계산하려면 Init을 다시 호출합니다.'),
  section('예제 코드 읽기','fetch로 얻은 md와 new로 얻은 ctx를 각각 RAII 핸들에 넣습니다. split은 바이트 길이를 반으로 나눕니다. 빈 문자열에서도 길이 0인 Update는 빈 입력을 계산하는 흐름에 사용할 수 있습니다.','Final의 length는 실제 출력 길이입니다. EVP_MAX_MD_SIZE 크기의 배열 전체를 출력하면 사용하지 않은 영역까지 표시하게 됩니다. SHA-256 결과는 32바이트, hex로는 64문자입니다.')],
 [api('EVP_MD_fetch(libctx, algorithm, properties)','nullptr: 기본 컨텍스트. algorithm="SHA256". properties로 구현 조건 지정.','반환 포인터는 소유한 참조입니다. EVP_MD_free 필요.','포인터 성공, nullptr 실패.','알고리즘이나 property 조건을 만족하는 구현이 없으면 실패합니다.'),
  api('EVP_DigestInit_ex2 / Update / Final_ex','ctx: 계산 상태. Init의 md: 구현. Final의 out: 충분한 버퍼, outlen: unsigned int* 출력 길이.','ctx는 EVP_MD_CTX_free. 입력·출력 버퍼는 호출자 소유.','각각 1 성공, 0 실패.','매 단계 결과를 확인하고 실패한 계산의 출력을 사용하지 않습니다.')],
 [step('입력 바이트 비교','개행이 추가된 세 번째 해시와 비교합니다.',build('digest','hash abc')+'\nprintf abc | openssl dgst -sha256\nprintf "abc\\n" | openssl dgst -sha256','처음 두 해시는 ba7816…로 같고 세 번째는 다릅니다.'),
  step('빈 입력','출력이 비어 있는 것과 빈 입력의 해시는 다릅니다.',build('digest',"hash ''"),'e3b0c442…로 시작하는 64문자')],
 ('Update를 두 번 호출하면 항상 해시도 달라지나요?',['같은 바이트를 같은 순서로 넣으면 같습니다','호출 횟수마다 달라집니다'],0,'호출 경계는 메시지에 추가되는 데이터가 아닙니다.'),['man3/EVP_DigestInit/'],'digest','split을 0, 1, message.size()로 바꿔 같은 결과를 확인하세요. CLI의 출력 라벨은 해시 바이트에 포함되지 않습니다.')

add('basic-random',1,'난수·비밀키·nonce 구분하기',25,
 '키를 만드는 난수는 예측하기 어려워야 합니다. nonce와 salt는 비밀이어야 하는지, 반복되면 어떤 문제가 생기는지부터 구분합니다.',
 ['비밀키는 보호해야 할 값입니다. nonce는 알고리즘별 유일성 규칙을 지켜야 하는 값이며 반드시 비밀인 것은 아닙니다.',
  'salt는 KDF의 입력을 구분하는 데 사용되며 보통 공개할 수 있습니다. salt를 추가한다고 약한 비밀번호가 고엔트로피 비밀이 되지는 않습니다.',
  'C++ rand()나 시간값으로 암호 키를 만들지 않습니다. OpenSSL 난수 API의 반환값을 검사합니다.'],
 [section('길이가 곧 엔트로피는 아니다','32바이트 배열을 만든 것만으로 256비트의 예측 불가능성이 생기지 않습니다. 배열을 채우는 난수 생성기의 성질이 중요합니다. 초기화된 0 배열이나 반복 문자열은 길이가 길어도 쉽게 예측됩니다.',
  'OpenSSL RAND API는 운영체제 등의 엔트로피 소스를 이용하는 난수 생성 체계에 연결됩니다. 애플리케이션에서 임의의 시드 문자열을 섞는 것이 이 체계를 개선한다고 가정하지 마세요.'),
  section('실패를 숨기지 않기','RAND_bytes_ex가 실패하면 출력은 키로 사용할 수 없습니다. 0으로 초기화된 배열을 계속 사용하는 것도 잘못입니다. 예제의 require는 예외를 발생시키고 이후 암호 연산을 중단합니다.','매번 다른 출력은 관찰할 수 있지만 두 번의 실행으로 난수 생성기의 통계적·암호학적 안전성을 증명할 수는 없습니다.')],
 [api('RAND_bytes_ex(ctx, buf, num, strength)','ctx=nullptr: 기본 컨텍스트. buf: 쓸 버퍼. num: 바이트 수. strength=0: 기본 강도 사용.','버퍼는 호출자 소유. num만큼 쓸 공간 확보.','1 성공, 그 외 실패로 처리.','실패 때 키 생성을 중단하고 오류 큐를 기록합니다. 같은 버퍼 내용을 정상 난수로 취급하지 않습니다.'),
  api('RAND_priv_bytes(buf, num)','개인적인 비밀값 생성을 위한 난수 API. num은 int.','결과 비밀의 저장·수명 관리는 호출자가 담당.','1 성공, 그 외 실패.','이 함수가 키 보관이나 자동 메모리 삭제까지 담당하는 것은 아닙니다.')],
 [step('난수 생성','각 결과는 32바이트입니다.',build('random_mac','random')+'\n./examples/cpp/random_mac random','서로 다른 64자리 hex 값'),
  step('CLI 비교','바이트 길이와 hex 길이를 비교합니다.','openssl rand -hex 32','64자리 hex + 줄바꿈')],
 ('GCM nonce는 반드시 비밀이어야 하나요?',['비밀보다 같은 키에서의 유일성이 핵심입니다','nonce만 숨기면 키는 공개해도 됩니다'],0,'키를 비밀로 유지하고 nonce 재사용을 피해야 합니다.'),['man3/RAND_bytes/'],'random_mac','32바이트 난수의 hex 길이가 64인 이유를 설명해 보세요. nonce를 암호 키와 같은 개념으로 취급하지 마세요.')

add('basic-mac',1,'HMAC: 해시에 비밀키를 더하는 이유',30,
 '공개된 해시와 달리 MAC 검증에는 비밀키가 필요합니다. 동일 키를 공유하는 두 당사자의 인증과 공개 검증 가능한 서명을 구분합니다.',
 ['HMAC은 정해진 구조로 해시와 키를 결합합니다. hash(key || message)를 임의로 대체 사용하지 않습니다.',
  'MAC은 비밀성을 제공하지 않습니다. 원문과 MAC을 같이 보내면 원문은 읽을 수 있습니다.',
  'MAC 키를 아는 누구나 새 MAC을 만들 수 있으므로 공개키 서명과 신뢰 모델이 다릅니다.'],
 [section('EVP_MAC의 인자 구성','OpenSSL 3의 EVP_MAC_fetch로 HMAC 구현을 가져오고, 그 구현으로 연산 컨텍스트를 생성합니다. HMAC이 사용할 해시 이름은 OSSL_PARAM 배열의 digest 항목으로 전달합니다.',
  'OSSL_PARAM_construct_*는 원래 버퍼를 가리키는 기술자를 만듭니다. 예제에서는 digest 문자열과 params 배열이 init 호출 동안 살아 있습니다. 임시 문자열의 data()를 오래 보관하지 마세요.'),
  section('검증과 오류 구분','예제의 key는 재현 가능한 테스트용 상수입니다. 실서비스 비밀키로 사용하지 않습니다. tamper 모드는 전송받은 MAC 한 바이트가 달라졌다고 가정합니다.','CRYPTO_memcmp는 같은 공개 길이의 두 메모리 구간을 비교합니다. 0이면 같고 0이 아니면 다릅니다. 일반 strcmp의 문자열 종료 규칙도, 대소 관계를 비교하는 규칙도 적용하지 않습니다.')],
 [api('EVP_MAC_init(ctx, key, keylen, params)','ctx: HMAC 상태. key/keylen: 비밀키 바이트와 길이. params: digest="SHA256" 등.','MAC과 MAC_CTX는 각각 free. params가 가리키는 데이터는 호출 동안 유지.','1 성공, 0 실패.','지원하지 않는 digest, 잘못된 설정 등이 실패 원인. 실패 후 final 결과를 사용하지 않습니다.'),
  api('EVP_MAC_final(ctx, out, outlen, outsize)','outsize는 버퍼 용량. outlen은 실제 길이를 받을 size_t*.','출력 버퍼는 호출자 소유.','1 성공, 0 실패.','버퍼 부족을 검사합니다. 반환된 outlen 범위만 사용합니다.'),
  api('CRYPTO_memcmp(a, b, len)','두 버퍼가 len 바이트 이상인지 먼저 확인합니다.','소유권 변화 없음.','0 동일, 비영(非零) 다름.','입력 내용에 따른 조기 종료 비교를 피합니다. 반환값을 정렬 순서로 해석하지 않습니다.')],
 [step('MAC 생성·검증','동일 입력이면 동일 MAC입니다.',build('random_mac','mac hello'),'MAC VERIFIED'),
  step('변조 거부','프로그램 종료 코드 2는 이 예제의 검증 거부 약속입니다.',build('random_mac','tamper hello')+'\necho "exit=$?"','MAC REJECTED, exit=2')],
 ('공유 MAC 키를 가진 상대도 새로운 MAC을 만들 수 있나요?',['예','아니요, 검증만 가능합니다'],0,'MAC은 공유 비밀 기반입니다. 공개키 서명과 구분하세요.'),['man3/EVP_MAC/','man3/CRYPTO_memcmp/'],'random_mac','message 한 글자와 key 한 글자를 각각 바꾸어 MAC이 바뀌는지 비교하세요.')

add('basic-kdf',1,'HKDF: 하나의 비밀에서 용도별 키 만들기',30,
 '키 교환 결과를 그대로 여러 암호 기능에 재사용하지 않고, 문맥을 구분하여 필요한 키 재료를 유도하는 이유를 배웁니다.',
 ['HKDF는 Extract와 Expand로 구성됩니다. salt와 입력 키 재료로 중간 비밀을 만들고 info와 출력 길이로 결과를 유도합니다.',
  'info는 용도 구분에 쓰이는 공개 문맥입니다. client traffic과 server traffic 같은 구분을 넣을 수 있습니다.',
  'HKDF는 비밀번호 추측을 느리게 만들기 위한 비용 조절형 비밀번호 KDF가 아닙니다.'],
 [section('같은 비밀, 다른 용도','송신과 수신 또는 암호화와 다른 기능의 키가 분리되면 같은 비밀에서 출발하더라도 용도 간 혼동을 줄일 수 있습니다. info의 바이트가 바뀌면 결과도 바뀝니다. 입력이 모두 같으면 결과는 결정적입니다.',
  '출력 길이를 길게 만든다고 원래 비밀에 없던 엔트로피가 생기지는 않습니다. HKDF는 비밀을 안전하게 다듬고 확장하는 구성요소이지 약한 비밀번호를 강하게 만드는 마법이 아닙니다.'),
  section('TLS와 연결하기','TLS 1.3은 HKDF와 transcript 해시를 포함하는 정해진 키 스케줄을 사용합니다. 예제는 HKDF의 개념을 보여주며 TLS의 HKDF-Expand-Label 인코딩과 전체 키 스케줄을 재현하지 않습니다.','OSSL_PARAM의 KEY, SALT, INFO는 바이트 버퍼입니다. 문자열 끝 NUL을 암묵적으로 포함하지 않습니다. params 배열의 끝에는 OSSL_PARAM_construct_end가 필요합니다.')],
 [api('EVP_KDF_fetch / EVP_KDF_CTX_new','"HKDF" 구현을 fetch한 후 그 구현의 연산 컨텍스트 생성.','KDF는 EVP_KDF_free, 컨텍스트는 EVP_KDF_CTX_free.','포인터 또는 nullptr.','fetch 실패와 컨텍스트 생성 실패를 각각 검사합니다.'),
  api('EVP_KDF_derive(ctx, out, outlen, params)','outlen: 원하는 결과 바이트 수. params: digest, key, salt, info. 기본 HKDF 모드는 extract-and-expand.','out과 모든 params 원본 버퍼는 호출 동안 유효.','1 성공, 0 실패.','필수 파라미터 누락, 지원하지 않는 설정, 허용 범위를 넘는 길이 등을 검사합니다.')],
 [step('용도별 키 비교','둘은 다른 결과여야 합니다.',build('kdf',"'client traffic'")+'\n./examples/cpp/kdf "server traffic"','서로 다른 32바이트 결과'),
  step('결정성 확인','동일 입력으로 두 번 실행합니다.','cd ~/lab\n./examples/cpp/kdf same\n./examples/cpp/kdf same','두 값이 같습니다.')],
 ('HKDF 출력 길이를 늘리면 입력 비밀의 엔트로피도 늘어나나요?',['아니요','예'],0,'출력 바이트 수와 입력의 예측 불가능성은 다릅니다.'),['man7/EVP_KDF-HKDF/','https://www.rfc-editor.org/rfc/rfc8446#section-7'],'kdf','info의 공백 하나를 바꾸어 보세요. 코드에서 salt와 info를 서로 바꾸면 같은 결과가 나올지 먼저 예측하세요.')

add('basic-aead',1,'AES-GCM: 복호화 성공과 인증 성공',40,
 'AEAD는 암호문과 추가 인증 데이터(AAD)의 무결성을 검증합니다. 가장 중요한 실습 규칙은 인증이 끝나기 전의 평문 후보를 외부에 사용하지 않는 것입니다.',
 ['GCM은 암호화된 본문과 인증 태그를 만듭니다. AAD는 숨기지 않지만 인증에 포함할 데이터입니다.',
  '같은 키에서 nonce를 재사용하면 보안이 무너질 수 있습니다. 예제는 실행마다 새 키와 새 12바이트 nonce를 생성합니다.',
  'DecryptUpdate가 성공해 평문 후보가 나와도 인증 성공이 아닙니다. DecryptFinal_ex의 결과가 인증 여부를 결정합니다.'],
 [section('다섯 입력의 역할','AES-256 키는 32바이트 비밀입니다. nonce는 이번 암호 연산을 구분하는 값이고, AAD는 인증만 할 부가 정보입니다. ciphertext는 암호화된 내용, tag는 인증 결과입니다. 수신자는 같은 키·nonce·AAD와 받은 tag를 사용해야 합니다.',
  '임의 길이 nonce를 기본값으로 가정하지 마세요. 이 예제는 GCM의 기본 12바이트 IV 길이를 사용합니다. 지속적으로 같은 키를 쓰는 설계에서는 nonce 생성·카운터·재시작·분산 사용 정책을 따로 설계해야 합니다.'),
  section('코드에서 신뢰 경계 찾기','EncryptUpdate에서 out=nullptr로 AAD를 전달합니다. 본문 암호화 후 Final을 확인하고 GET_TAG로 태그를 얻습니다. 복호화에서도 AAD와 본문을 순서대로 넣고 SET_TAG로 기대 태그를 지정합니다.',
  'candidate 배열은 인증 전 데이터입니다. Final 실패 시 지우고 종료 코드 2로 거부합니다. 태그·AAD·암호문 중 무엇을 바꾸어도 같은 거부 경로로 가야 합니다. 오류 큐에 상세 문자열이 없더라도 인증 실패 반환값은 반드시 처리해야 합니다.')],
 [api('EVP_EncryptInit_ex2(ctx, cipher, key, iv, params)','AES-256-GCM 구현, 32바이트 키, 기본 12바이트 IV. params=nullptr은 추가 설정 없음.','cipher/context 각각 free. key·iv 버퍼는 호출자 소유.','1 성공, 0 실패.','키/IV 길이는 배열의 크기만 보고 자동 추론하지 않습니다. 알고리즘의 요구를 맞춰야 합니다.'),
  api('EVP_DecryptUpdate(ctx, out, outl, in, inl)','inl은 int. out에는 아직 인증되지 않은 평문 후보가 기록됩니다.','버퍼 용량을 확보하고 대용량 size_t→int 변환은 범위를 확인해야 합니다.','1은 처리 성공이며 최종 인증 성공이 아닙니다.','candidate를 HTTP 파서·파일·사용자에게 먼저 넘기지 않습니다.'),
  api('EVP_DecryptFinal_ex(ctx, out, outl)','기대 tag 설정 후 최종 인증 검사.','성공 뒤에만 후보 평문을 채택합니다.','GCM에서 양수 성공, 0 이하 실패로 처리.','인증 실패 시 후보를 폐기합니다. 재시도로 같은 변조 데이터를 신뢰하게 만들지 않습니다.')],
 [step('정상 왕복','암호화와 복호화 컨텍스트를 별도로 사용합니다.',build('aead'),'AUTH OK: authenticated message'),
  step('세 가지 변조','각각 exit=2여야 합니다.','cd ~/lab\nfor mode in tag aad ciphertext; do ./examples/cpp/aead "$mode"; echo "exit=$?"; done','모두 AUTH REJECTED; candidate plaintext discarded')],
 ('DecryptUpdate가 1을 반환했을 때 평문을 바로 처리해도 되나요?',['예','아니요, 태그를 설정하고 Final 인증까지 성공해야 합니다'],1,'처리 성공과 인증 성공을 분리해야 합니다.'),['man3/EVP_EncryptInit/','man7/EVP_CIPHER-AES/'],'aead','인증 성공 출력 위치를 찾아보세요. 인증 전 후보를 출력하는 코드가 왜 위험한지 설명해 보세요.')

add('basic-kex',1,'X25519: 공개값으로 공유 비밀 합의하기',35,
 '서로의 개인키를 전달하지 않고 같은 공유 비밀에 도달하는 과정을 코드로 확인합니다. 여기에는 아직 상대의 신원 인증이 없습니다.',
 ['Alice 개인키 + Bob 공개키와 Bob 개인키 + Alice 공개키로 계산한 공유 비밀은 같습니다.',
  'X25519는 키 교환, Ed25519는 서명 알고리즘입니다. 이름이 비슷해도 서로 바꿔 사용할 수 없습니다.',
  '키 교환 결과는 일반적으로 KDF의 입력으로 사용합니다. 이 실습은 공유 비밀 자체를 화면에 출력하지 않습니다.'],
 [section('공개키만 전달하기','예제는 각 키에서 raw 공개키를 추출해 새로운 공개키 전용 객체를 만듭니다. derive에는 자신의 개인키 객체와 상대의 공개키 객체를 전달합니다. 상대의 개인키를 사용할 필요가 없습니다.',
  '두 계산이 같은 값이라는 것은 수학적 합의 성공입니다. 그 공개키가 진짜 Bob의 것인지 인증되었다는 뜻은 아닙니다. TLS의 인증서·CertificateVerify가 왜 별도로 필요한지 연결해 보세요.'),
  section('두 단계 출력 버퍼 API','EVP_PKEY_derive(ctx, nullptr, &size)로 필요한 길이를 질의하고, 그 길이의 벡터를 할당한 뒤 다시 호출합니다. 두 번째 호출에서 size는 버퍼 용량을 입력하고 실제 길이를 출력받는 인자입니다.',
  'bad-peer 모드는 Ed25519 키를 상대 키로 넣습니다. 이 호출이 실패하면 실패한 ctx에서 계속 derive하지 않고 계산을 중단합니다.')],
 [api('EVP_PKEY_CTX_new_from_pkey(libctx, pkey, properties)','pkey: 자신의 키 교환 개인키. libctx/properties: 구현 선택 환경.','반환 ctx는 EVP_PKEY_CTX_free. 키 핸들도 별도로 관리하며 예제는 ctx보다 오래 유지합니다.','포인터 또는 nullptr.','키 타입과 연산 지원 여부를 확인합니다.'),
  api('EVP_PKEY_derive_init / derive_set_peer / derive','초기화 → peer 지정 → 길이 질의 → 비밀 계산.','입출력 버퍼와 peer 키의 수명을 호출 동안 유지합니다.','성공 1, 실패 0 또는 음수. -2는 미지원 연산을 나타낼 수 있습니다.','1과 비교하세요. 단순히 if(ret)로 검사하면 음수 실패를 성공으로 오해합니다.')],
 [step('공유 비밀 비교','개인키 두 개를 교환하지 않고 공개키 객체만 전달합니다.',build('kex'),'SHARED SECRET MATCH; size=32; peer identity NOT authenticated'),
  step('잘못된 키 타입', '실패 반환값과 오류 큐를 확인합니다.',build('kex','bad-peer')+'\necho "exit=$?"','set peer 오류, exit=1')],
 ('공유 비밀이 일치하면 상대의 신원도 확인된 것인가요?',['아니요, 인증은 별도입니다','예'],0,'공개키를 신뢰할 상대와 연결하는 인증 절차가 필요합니다.'),['man3/EVP_PKEY_derive/','man7/EVP_PKEY-X25519/'],'kex','derive 결과를 HKDF에 넣는다면 info를 어떤 용도로 나눌지 설계해 보세요. 직접 만든 구성을 TLS 대체 프로토콜로 사용하지는 마세요.')

add('tls-record',1,'TLS record와 애플리케이션 바이트',30,
 'TLS는 애플리케이션에 신뢰할 수 있는 바이트 스트림을 제공하지만 HTTP 메시지 경계를 만들어 주지는 않습니다. TCP 패킷·TLS record·read 호출을 구분합니다.',
 ['한 번의 SSL_write가 한 번의 상대 SSL_read로 대응한다고 가정하지 않습니다.',
  'TLS 1.3의 record 보호에는 AEAD와 방향별 키, record 순서에 기반한 nonce 구성이 사용됩니다.',
  'SSL_read_ex의 실제 수신 길이만 처리합니다. 요청한 버퍼 크기를 채울 때까지 반드시 기다리는 API가 아닙니다.'],
 [section('세 가지 경계','TCP는 바이트 스트림이고 패킷 경계는 애플리케이션 메시지 경계가 아닙니다. TLS는 record로 바이트를 보호하지만 호출자가 보게 되는 read 결과도 애플리케이션 프레임과 일대일 대응하지 않습니다.',
  'HTTP 파서는 Content-Length, chunked encoding 또는 연결 종료 같은 프로토콜 규칙으로 메시지 끝을 판단해야 합니다. 예제는 HTTP/1.0 close 응답을 관찰하고 첫 줄만 출력하며 완전한 HTTP 파서를 구현하지 않습니다.'),
  section('길이와 pending','SSL_read_ex가 1을 반환하면 received 바이트를 붙입니다. 2048바이트 배열을 64바이트로 줄여도 누적 결과는 같아야 합니다. read 호출 횟수는 늘 수 있습니다.',
  '커널 소켓이 readable이 아니어도 OpenSSL 내부에 복호화된 데이터가 남아 있을 수 있습니다. SSL_pending은 즉시 읽을 수 있는 처리된 애플리케이션 바이트를 알려주지만 0이 항상 다음 SSL_read가 진행할 수 없다는 뜻은 아닙니다.')],
 [api('SSL_read_ex(ssl, buf, num, readbytes)','num: 최대 용량. readbytes: 실제 바이트 수를 받을 size_t*.','buf는 호출자 소유. 1일 때 실제 수신 범위만 사용.','1 성공, 0이면 SSL_get_error로 분류.','0을 곧바로 TCP EOF로 해석하지 않습니다. WANT, close_notify, 치명적 오류를 구분합니다.'),
  api('SSL_pending(ssl)','현재 연결에서 즉시 읽을 수 있는 처리된 애플리케이션 데이터 양.','ssl은 여전히 연결 소유자에게 속함.','0 이상의 바이트 수.','0만 보고 TLS 내부의 모든 진행 가능성이 없다고 단정하지 않습니다.')],
 [step('작은 버퍼로 응답 읽기','예제의 buffer 크기를 2048에서 64로 바꿔 다시 실행해 보세요.',build('tls_client'),'HTTP/1.0 200 ok, application bytes=…'),
  step('record 관찰','-msg 출력의 record와 handshake 이름을 비교합니다.','openssl s_client -connect 127.0.0.1:4433 -servername localhost -CAfile ~/lab/tls/ca.pem -verify_hostname localhost -verify_return_error -tls1_3 -msg </dev/null 2>&1 | head -n 55','RecordHeader와 Handshake 메시지가 서로 다른 층으로 출력됩니다.')],
 ('SSL_read_ex가 반환하는 데이터는 항상 HTTP 응답 한 개 전체인가요?',['아니요, 실제 길이만큼의 바이트입니다','예'],0,'메시지 조립은 애플리케이션 프로토콜의 책임입니다.'),['man3/SSL_read/','man3/SSL_pending/'],'tls_client','버퍼 크기를 바꾸기 전후 첫 HTTP 상태 줄과 누적 바이트 수를 비교하세요. 서버 상태 출력은 연결마다 일부 달라질 수 있습니다.')

add('tls-shutdown',1,'close_notify와 갑작스러운 EOF',30,
 '정상적인 TLS 종료와 단순한 소켓 끊김을 구분합니다. 정상 서버와 close_notify 없이 끊는 실험 서버를 비교합니다.',
 ['close_notify는 TLS 계층의 정상 종료 알림입니다. TCP FIN만으로는 TLS 메시지가 끝까지 왔다는 보장을 대체할 수 없습니다.',
  'OpenSSL 3에서는 예기치 않은 EOF가 SSL_ERROR_SSL과 unexpected eof while reading 이유로 보고될 수 있습니다.',
  '치명적 TLS 오류 이후에는 SSL_shutdown을 다시 시도하는 정상 종료 흐름으로 들어가지 않습니다.'],
 [section('shutdown은 0도 의미가 있다','SSL_shutdown의 1은 양방향 종료 완료입니다. 0은 자신이 close_notify를 보냈으나 상대의 종료 알림을 아직 받지 못한 상태로 해석해야 합니다. 음수는 SSL_get_error로 분류합니다.',
  '자신이 먼저 종료하는 경우에도 상대의 남은 데이터를 읽어야 할 수 있습니다. 이 예제는 서버 응답을 close_notify까지 읽은 다음 자신의 종료 알림을 보냅니다. 일반적인 양방향 프로토콜의 종료 상태 머신 전체를 대체하는 코드는 아닙니다.'),
  section('실패 실험의 구조','failure_lab.py는 임시 포트의 로컬 TLS 서버를 실행합니다. 핸드셰이크와 요청 수신 후 TLS shutdown 없이 소켓을 닫습니다. tls_client가 이를 정상 EOF로 처리하지 않고 오류로 종료하는지 확인합니다.',
  '검사를 통과시키려고 SSL_OP_IGNORE_UNEXPECTED_EOF를 켜지 않습니다. 애플리케이션의 메시지 길이 규칙과 절단 공격 가능성을 이해한 후에야 별도 정책을 논의할 수 있습니다.')],
 [api('SSL_shutdown(ssl)','현재 TLS 연결의 종료 프로토콜 진행.','SSL_free와 다릅니다. SSL_free가 종료 알림 전송을 대신하지 않습니다.','1 완료, 0 아직 상대 종료 대기, 음수는 SSL_get_error.','WANT이면 준비된 뒤 재호출. 치명적 오류 뒤에는 종료 프로토콜을 더 진행하지 않습니다.'),
  api('SSL_get_error(ssl, ret)','방금 호출한 TLS I/O의 정확한 반환값 전달.','동일 스레드에서, 중간 OpenSSL 호출 없이 검사. 호출 전 오류 큐는 비워 둡니다.','ZERO_RETURN, WANT_READ/WRITE, SSL_ERROR_SSL 등 분류값.','분류 전에 ERR_get_error/ERR_print_errors_fp를 호출하면 큐가 바뀌어 오진할 수 있습니다.')],
 [step('정상 종료','상대 종료 알림과 shutdown 완료를 관찰합니다.',build('tls_client'),'peer close_notify received / shutdown complete'),
  step('비정상 종료','실험 서버는 정상 학습 TLS 서버와 다른 임시 포트를 사용합니다.','cd ~/lab\npython /opt/scripts/failure_lab.py examples/cpp/tls_client','unexpected eof while reading 및 PASS: abrupt EOF rejected')],
 ('SSL_shutdown 반환값 0은 무조건 치명적 오류인가요?',['아니요, 종료가 아직 완료되지 않은 상태일 수 있습니다','예'],0,'일반 TLS I/O와 shutdown의 반환값 규약을 각각 읽어야 합니다.'),['man3/SSL_shutdown/','man3/SSL_get_error/'],'tls_client','정상 서버와 절단 서버의 출력에서 ZERO_RETURN과 SSL_ERROR_SSL이 어떻게 갈리는지 찾아보세요.')

add('x509-chain',2,'체인 구축과 신뢰 앵커를 분리하기',35,
 'root → intermediate → leaf의 세 단계 체인을 만들고, 서버가 보내는 중간 인증서와 로컬에서 신뢰하는 루트 인증서를 구분합니다.',
 ['서명을 검증할 공개키를 찾는 경로 구축과 그 경로를 신뢰 정책에 맞게 검증하는 것은 연결되지만 다른 작업입니다.',
  '-untrusted는 체인 구축에 사용할 후보 중간 인증서입니다. 그 인증서를 자동으로 신뢰 앵커로 승격하지 않습니다.',
  '자체 서명 인증서는 스스로 신뢰를 만들어 내지 않습니다. 검증자의 외부 설정이 신뢰 앵커를 정합니다.'],
 [section('중간 인증서가 필요한 이유','leaf의 Issuer가 intermediate이면 root 공개키로 leaf 서명을 직접 검증할 수 없습니다. intermediate를 찾아 leaf 서명을 확인하고, 다시 root로 intermediate 서명을 확인해야 합니다.',
  '이 실습에서는 root에 pathlen:1, intermediate에 pathlen:0을 설정합니다. intermediate가 또 다른 하위 CA를 발급하는 체인은 이 제약에 부합하지 않습니다. 이름 문자열이 같다는 것만으로 체인이 성립하지 않습니다.'),
  section('실패를 읽는 순서','중간 인증서를 제공하지 않으면 local issuer를 찾지 못할 수 있습니다. 중간 인증서를 제공한 뒤에도 root 신뢰, 유효기간, 이름, CA 제약, 목적 등의 검증이 남습니다.',
  '이 환경의 verify는 AIA URL에서 누락된 intermediate를 자동 다운로드하는 실습이 아닙니다. 필요한 체인 후보를 명시적으로 제공합니다. 폐기(CRL/OCSP) 정책은 기본 체인 성공과 별도로 설계해야 합니다.')],
 [api('X509_STORE / X509_STORE_CTX','STORE는 신뢰 인증서·검증 설정, STORE_CTX는 특정 검증 작업의 상태.','각각 new/free. 입력 leaf와 untrusted 체인 수명을 검증 동안 유지.','new는 포인터 또는 nullptr. verify는 별도 반환값.','한 검증 결과를 다른 leaf 검증에 재사용하지 않습니다. STORE_CTX 재사용 시 올바르게 재초기화합니다.')],
 [step('체인 발급','이 레슨 전용 chain 폴더의 인증서를 생성합니다. 재실행하면 이 폴더의 실습 인증서를 다시 발급합니다.','bash /opt/scripts/make-chain.sh ~/lab/chain','root.pem, intermediate.pem, leaf.pem'),
  step('누락과 성공 비교','첫 검증 실패와 두 번째 성공을 비교합니다.','cd ~/lab/chain\nopenssl verify -CAfile root.pem leaf.pem\nopenssl verify -CAfile root.pem -untrusted intermediate.pem -purpose sslserver -verify_hostname chain.local leaf.pem','첫 명령 issuer 오류, 두 번째 leaf.pem: OK')],
 ('-untrusted intermediate.pem은 intermediate를 신뢰 앵커로 지정하나요?',['아니요, 경로 구축 후보입니다','예'],0,'신뢰할 앵커와 경로를 이어 줄 후보를 구분해야 합니다.'),['man1/openssl-verify/','man3/X509_STORE_CTX_new/'],None,'root 대신 다른 CA를 주거나 verify_hostname을 바꾸어 어느 검증 단계에서 실패하는지 비교하세요.')

add('x509-api',2,'C++에서 인증서 파싱·검증하기',40,
 'PEM을 읽는 성공과 인증서를 신뢰할 수 있다는 판단을 분리합니다. OpenSSL 객체의 소유권과 검증 오류 코드를 직접 다룹니다.',
 ['파싱은 데이터 형식을 읽는 작업이며 서명·체인·이름 검증을 대신하지 않습니다.',
  'X509_NAME 같은 내부 객체를 get으로 얻었을 때 문서에서 소유권을 확인해야 합니다.',
  '검증 거부는 일반 오류 큐보다 X509_STORE_CTX의 error와 depth로 먼저 진단합니다.'],
 [section('코드의 객체 수명','BIO_new_file로 입력을 열고 PEM_read_bio_X509에 두 번째 인자 nullptr을 주어 새 X509를 반환받습니다. 인증서는 Cert 핸들이 소유합니다. X509_get_subject_name은 그 내부 이름을 빌려주며 별도로 free하지 않습니다.',
  'store와 cert는 검증 ctx보다 먼저 선언되어 더 오래 유지됩니다. ctx가 참조하는 입력을 먼저 해제하면 안 됩니다. stdout BIO에는 BIO_NOCLOSE를 사용하여 BIO를 해제해도 stdout을 닫지 않습니다.'),
  section('검증 파라미터의 의미','get0_param으로 얻은 파라미터 객체는 ctx 소유입니다. set1_host의 길이 0은 NUL 종료 이름 문자열을 사용한다는 뜻입니다. sslserver 목적을 지정하고 X509_verify_cert를 호출합니다.',
  '성공 1, 검증 실패 0, 예외적 오류 음수를 구분합니다. 이 프로그램은 정상 0, 검증 거부 2, 기타 실패 1이라는 프로세스 종료 코드로 변환합니다. API 반환값과 프로그램 종료 코드는 서로 다른 규약입니다.')],
 [api('PEM_read_bio_X509(bio, nullptr, nullptr, nullptr)','입력 BIO에서 PEM 인증서 파싱. 두 번째 nullptr로 새 객체 반환.','반환 X509는 X509_free. 입력 BIO는 따로 해제.','X509* 또는 nullptr.','PEM 형식 오류·파일 종류 오류를 검사합니다. 파싱 성공을 인증 성공으로 사용하지 않습니다.'),
  api('X509_STORE_CTX_init(ctx, store, leaf, untrusted)','신뢰 store, 대상 leaf, 후보 intermediate 스택(없으면 nullptr).','store/leaf/untrusted는 호출자가 검증 수명 동안 유지. ctx는 free 필요.','1 성공, 0 실패.','초기화 실패 때 verify를 호출하지 않습니다.'),
  api('X509_verify_cert(ctx)','ctx의 신뢰·이름·용도·시간 설정으로 검증.','ctx에 검증 결과가 기록됩니다.','1 성공, 0 검증 거부, 음수 예외적 오류.','X509_STORE_CTX_get_error / get_error_depth로 이유·단계를 확인합니다.')],
 [step('파싱과 정상 검증','출력되는 Subject와 실제 검증 결과를 구분합니다.',build('x509'),'CN=localhost / CHAIN + HOST + PURPOSE OK'),
  step('이름과 파일 오류','첫 실행은 검증 거부, 두 번째는 입력 파일 오류입니다.',build('x509','~/lab/tls/server.pem ~/lab/tls/ca.pem wrong.example')+'\necho "exit=$?"\n./examples/cpp/x509 /missing.pem\necho "exit=$?"','hostname mismatch exit=2 / open PEM exit=1')],
 ('PEM_read_bio_X509가 성공하면 신뢰 검증도 끝났나요?',['아니요','예'],0,'파싱 결과를 정책에 따라 별도로 검증해야 합니다.'),['man3/PEM_read_bio_PrivateKey/','man3/X509_verify_cert/','man3/X509_STORE_CTX_new/'],'x509','ca 경로를 잘못된 파일로 바꾸고, 파일 로딩 실패와 체인 검증 실패가 어떻게 다른지 설명하세요.')

add('arch-ownership',3,'소유권·참조 카운트·RAII',40,
 'OpenSSL C API를 C++에서 안전하게 사용하려면 포인터의 주소보다 누가 어떤 참조를 소유하는지 이해해야 합니다. 예외 경로도 정상 경로와 같은 해제 규칙을 지켜야 합니다.',
 ['new/fetch 결과, get0로 빌린 포인터, get1 또는 up_ref로 얻은 참조는 해제 책임이 다릅니다.',
  'get0/get1/set0/set1은 유용한 관례지만 모든 함수의 소유권을 이름만으로 추론하지 말고 해당 문서를 확인합니다.',
  'RAII는 이미 잘못 부여한 소유권을 고쳐주지 않습니다. 빌린 포인터를 owning unique_ptr에 넣으면 이중 해제를 만들 수 있습니다.'],
 [section('주소와 소유권은 다르다','first와 second는 같은 EVP_PKEY 주소를 가리킬 수 있지만 up_ref 성공 뒤에는 각각 한 참조를 소유합니다. first.reset()은 참조 하나를 내려놓는 것이며 second가 남아 있으면 객체는 살아 있습니다.',
  'up_ref 없이 같은 주소를 두 unique_ptr에 넣으면 두 번 해제할 위험이 있습니다. 반대로 std::move는 참조 카운트를 늘리지 않고 소유자를 옮깁니다. 이동된 unique_ptr은 비어 있습니다.'),
  section('공통 헤더 읽기','study.hpp의 Handle<T, Free>는 OpenSSL 타입에 맞는 해제 함수를 호출합니다. 선언의 역순으로 지역 객체가 파괴되므로 의존하는 객체를 뒤에 선언합니다. 예외가 발생해도 스택이 풀리면서 핸들이 정리됩니다.',
  'get()은 소유권을 넘기지 않습니다. 소유권을 받는 set0 API를 사용하는 상황에서는 문서의 성공·실패 시 규칙을 확인한 뒤 release 시점을 결정해야 합니다. 이 예제는 문서가 다른 여러 set0 함수에 공통 규칙을 강요하지 않습니다.')],
 [api('EVP_PKEY_up_ref(pkey)','현재 유효한 키의 참조 수를 증가시킵니다.','성공하면 추가 참조 하나를 EVP_PKEY_free로 내려놓을 책임이 생깁니다.','1 성공, 0 실패.','성공 확인 전에 두 번째 owning 핸들을 만들지 않습니다.'),
  api('SSL_get1_peer_certificate(ssl)','연결 상대의 인증서 참조를 반환.','호출자가 X509_free할 참조. get0 변형의 빌린 포인터와 다릅니다.','X509* 또는 nullptr.','인증서가 없는 경우를 처리합니다. 반환된 인증서 존재 자체가 검증 성공은 아닙니다.')],
 [step('참조 수명 확인','up_ref, reset, move를 순서대로 읽습니다.',build('ownership'),'REFERENCE OK / MOVE OK'),
  step('예외 경로','의도적 예외를 통해 RAII가 적용되는 범위를 찾습니다.',build('ownership','throw')+'\necho "exit=$?"','intentional exception, exit=1')],
 ('get0로 빌린 포인터를 바로 owning unique_ptr에 넣어도 되나요?',['아니요, 소유권이 없기 때문입니다','예'],0,'먼저 소유권 계약을 확인하고, 필요하면 문서가 허용하는 참조 증가·복제 방법을 사용합니다.'),['man3/EVP_PKEY_new/','man3/SSL_get_peer_certificate/'],'ownership','study.hpp에서 BIO_free가 int를 반환해도 deleter가 사용 가능한 이유를 설명하세요. 디버그 시 -fsanitize=address 사용도 연습할 수 있습니다.')

add('arch-bio',3,'BIO: 소켓이 아닌 I/O 추상화',30,
 'BIO는 메모리, 파일, 소켓 등 다양한 I/O를 같은 계열 API로 다루는 추상화입니다. memory BIO를 통해 버퍼와 재시도 규칙을 관찰합니다.',
 ['BIO_s_mem은 메모리 BIO의 method를 제공하고 BIO_new가 실제 상태 객체를 만듭니다.',
  'BIO_get_mem_data의 내부 버퍼 포인터는 빌린 뷰입니다. 별도로 free하거나 수정 뒤에도 유효하다고 가정하지 않습니다.',
  'memory BIO의 빈 입력과 소켓의 EOF는 동일한 개념이 아닙니다. 반환값과 BIO_should_retry를 함께 읽습니다.'],
 [section('write와 read 사이','A NUL B를 BIO에 쓰고 내부 메모리 뷰를 출력합니다. 그 뒤 read를 수행하면 입력이 소비됩니다. 문자열 API처럼 NUL에서 멈추지 않고 실제 길이를 사용합니다.',
  '이 예제의 writable memory BIO는 기본 설정에서 비어 있을 때 read가 음수이며 retry가 설정됩니다. EOF 반환 동작은 BIO_set_mem_eof_return 같은 설정에 따라 달라질 수 있습니다.'),
  section('TLS와 연결하는 지점','SSL은 암호화된 데이터를 transport BIO로 읽고 씁니다. 직접 소켓 BIO를 쓰는 모델과 memory BIO를 통해 외부 이벤트 루프가 암호화 바이트를 운반하는 모델을 구분할 수 있습니다.',
  'SSL_set_bio, SSL_set0_rbio/wbio의 소유권 규칙은 단순히 포인터 두 개를 보관하는 것보다 복잡합니다. 처음에는 SSL_set_fd 방식의 학습 클라이언트로 상태 흐름을 익힌 뒤 BIO 연결을 확장하세요.')],
 [api('BIO_new(BIO_s_mem())','method를 사용해 새 memory BIO 생성.','반환 BIO는 BIO_free. BIO_s_mem의 method 자체는 해제하지 않습니다.','포인터 또는 nullptr.','BIO_new 실패 확인 후에만 read/write.'),
  api('BIO_get_mem_data(bio, &ptr)','ptr로 내부 데이터 주소를 전달하고 길이를 반환.','ptr은 borrowed. BIO 변경·읽기·해제 뒤 계속 사용하지 않습니다.','현재 데이터 길이.','내부 ptr을 OPENSSL_free하지 않습니다.'),
  api('BIO_read_ex / BIO_write_ex','버퍼 포인터, 용량/입력 길이, 실제 처리 길이 출력 인자.','입출력 버퍼는 호출자 소유.','1 성공, 0이면 BIO의 재시도·오류 규칙 확인.','SSL_get_error는 일반 BIO 반환값의 해석 함수가 아닙니다.')],
 [step('바이너리 왕복','NUL이 있어도 3바이트가 유지됩니다.',build('bio'),'borrowed view=410042 / read=3 hex=410042'),
  step('빈 BIO','이 예제의 기본 memory BIO 설정에서 관찰합니다.',build('bio','empty'),'empty read=-1 retry=1')],
 ('BIO 내부 메모리 포인터를 누가 해제하나요?',['BIO 소유자가 BIO를 정리하며 관리됩니다','뷰를 받은 쪽이 항상 free합니다'],0,'빌린 뷰를 소유한 메모리처럼 취급하지 않습니다.'),['man3/BIO_s_mem/','man3/BIO_read/'],'bio','read 전후 BIO_ctrl_pending 값을 출력해 보세요. 읽은 바이트가 왜 줄어드는지 설명하세요.')

add('arch-errors',3,'반환값과 스레드별 오류 큐',35,
 'OpenSSL의 모든 실패를 같은 규칙으로 처리하면 안 됩니다. 반환값이 1/0인지, 포인터인지, 길이인지, 음수 상태인지 먼저 문서에서 확인합니다.',
 ['EVP 함수의 1 성공 규칙, 포인터 API의 nullptr 실패, CRYPTO_memcmp의 0 동일 규칙은 서로 다릅니다.',
  '오류 큐는 현재 스레드에 속합니다. ERR_get_error는 항목을 꺼내고 ERR_peek_error는 꺼내지 않습니다.',
  'SSL_get_error는 오류 큐 내용에도 의존합니다. TLS 호출과 오류 분류 사이에 다른 OpenSSL 호출을 넣지 않습니다.'],
 [section('반환값은 주 신호다','오류 큐를 먼저 보고 성공 여부를 판단하지 않습니다. 함수 반환값으로 성공·실패를 판정한 뒤 필요한 오류 정보를 읽습니다. 이전 실패가 큐에 남아 있으면 나중의 로그가 오해를 만들 수 있습니다.',
  '예제는 존재하지 않는 digest를 fetch해 실패를 만들고 peek, drain, 정상 fetch를 비교합니다. 실패를 처리한 후 다음 작업으로 복구하는 경계를 눈으로 확인하세요.'),
  section('TLS 호출의 특별한 규칙','이전 작업 오류를 이미 기록·처리한 경계에서 ERR_clear_error로 큐를 비웁니다. TLS I/O를 호출하고 실패하면 정확한 ret를 같은 스레드의 SSL_get_error에 전달합니다. 분류가 끝난 뒤 오류 큐를 로깅합니다.',
  '매 함수 앞에서 무작정 ERR_clear_error를 호출하면 아직 기록하지 않은 진단 정보를 잃습니다. 예제의 TLS 루프는 각 실패를 즉시 분류하고 치명적 오류를 기록하므로 다음 시도 전 큐 정리가 명확합니다.')],
 [api('ERR_peek_error / ERR_get_error','현재 스레드 오류 큐의 항목 조회. 인자 없음.','숫자 코드 반환이며 메모리 해제 대상 아님.','0: 큐가 비어 있음. get은 항목 제거, peek은 유지.','다른 스레드로 넘겨 원래 오류를 읽을 수 있다고 가정하지 않습니다.'),
  api('SSL_get_error(ssl, ret)','실패한 SSL I/O와 동일한 ssl 및 원본 ret.','상태 조회이며 소유권 이동 없음.','WANT_READ/WRITE는 진행을 위한 재시도 조건. SSL_ERROR_SSL 등은 다른 경로.','ERR_print_errors_fp를 먼저 호출해 오류 큐를 비우면 분류가 달라질 수 있습니다.')],
 [step('오류 큐 실험','출력의 fetch 실패 이유와 마지막 복구 성공을 함께 읽습니다.',build('errors'),'PEEK leaves queue intact / DRAINED; recovery OK'),
  step('다른 실패 형태 비교','반환값이 0이라는 이유로 모두 같은 의미가 되지는 않습니다.',build('aead','tag')+'\necho "example exit=$?"','인증 거부와 exit=2. fetch 오류와 다른 종류의 실패입니다.')],
 ('SSL_read_ex 실패 뒤 ERR_print_errors_fp를 먼저 호출해도 되나요?',['아니요, SSL_get_error를 먼저 호출해야 합니다','예'],0,'오류 큐를 소비하기 전에 TLS 오류를 분류해야 합니다.'),['man3/ERR_get_error/','man3/SSL_get_error/'],'errors','로그 함수가 내부에서 OpenSSL을 호출한다면 TLS 실패와 SSL_get_error 사이에 넣을 수 있는지 검토하세요.')

add('code-nonblock',4,'nonblocking TLS와 epoll 재시도',50,
 '앞에서 이해한 TLS API를 준비 이벤트에 따라 재호출합니다. 프록시 로직은 넣지 않고 단일 TLS 클라이언트의 상태 진행에 집중합니다.',
 ['SSL_read가 WANT_WRITE, SSL_write가 WANT_READ를 요구할 수 있습니다. 호출 이름이 아니라 SSL_get_error 결과로 대기 방향을 정합니다.',
  'WANT는 그 호출의 작업이 끝났다는 뜻이 아닙니다. 완료될 때까지 필요한 인자와 버퍼를 유지합니다.',
  '예제는 level-triggered epoll, 단일 스레드, 절대 deadline을 사용합니다. 여러 연결의 생산용 이벤트 루프를 구현한 것은 아닙니다.'],
 [section('TCP와 TLS 상태를 따로 보기','nonblocking connect의 EINPROGRESS는 TCP 연결 진행 중입니다. EPOLLOUT 후 SO_ERROR를 확인해야 TCP 연결 성공 여부를 알 수 있습니다. 그다음 SSL_connect의 TLS 상태 머신을 진행합니다.',
  'SSL_connect가 WANT_READ이면 읽기 준비를 기다렸다 같은 SSL_connect를 다시 호출합니다. epoll 이벤트가 성공을 보증하지는 않습니다. HUP/ERR도 준비를 깨울 수 있으므로 다음 SSL 호출이 실제 결과를 분류합니다.'),
  section('쓰기 재시도의 불변 조건','WANT가 나온 write는 같은 데이터·길이로 재시도합니다. 이 예제는 포인터도 동일하게 유지합니다. offset은 성공할 때만 증가합니다. SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER 등의 옵션을 쓰면 계약을 다시 확인해야 합니다.',
  'partial write 모드를 사용하지 않은 기본 write_ex 성공은 요청한 버퍼가 처리된 상태입니다. 예제는 실제 written을 이용해 누적하는 형태로 작성합니다. 무한 즉시 재호출 대신 필요한 준비 이벤트를 기다리므로 busy loop를 피합니다.'),
  section('종료·시간 제한','deadline은 각 WANT마다 새로 8초로 늘리지 않고 전체 작업 기준으로 유지합니다. read의 ZERO_RETURN은 정상 peer close_notify입니다. 그 외 치명적 오류는 정상 shutdown 루프를 거치지 않고 RAII로 자원을 정리합니다.','이벤트 루프의 모든 pending 작업을 나타내는 일반 프레임워크는 아닙니다. 실제 프로그램에서는 버퍼 소유 객체, 취소, 이벤트 등록 해제, 연결 수명을 함께 설계해야 합니다.')],
 [api('SSL_connect(ssl)','client handshake 진행. SSL_set_fd와 인증 정책을 미리 설정합니다.','ssl은 재시도 사이에도 같은 객체여야 합니다.','1 성공, 그 외 SSL_get_error.','WANT는 대기 뒤 재호출. 인증서 오류는 재시도로 우회하지 않습니다.'),
  api('SSL_write_ex(ssl, buf, num, written)','buf/num: 쓰려는 동일 데이터 구간. written: 성공 시 실제 길이.','pending write의 버퍼를 수정·해제하지 않습니다.','1 성공, 0은 SSL_get_error로 분류.','WANT에서 offset을 미리 증가시키면 데이터가 누락됩니다.'),
  api('SSL_set_fd(ssl, fd)','SSL의 socket BIO를 해당 파일 디스크립터에 연결.','이 사용 방식에서 fd는 호출자 소유이며 SSL_free가 close를 대신하지 않습니다.','1 성공, 0 실패.','소켓을 먼저 닫고 SSL I/O를 계속 호출하지 않습니다.')],
 [step('동기와 비교','동일 검증 정책과 HTTP 요청으로 비교합니다.',build('tls_client','blocking')+'\n./examples/cpp/tls_client nonblock','둘 다 검증과 정상 종료 성공; nonblock에는 WANT → epoll 로그'),
  step('실패 재시도 금지','호스트 이름 오류는 WANT와 다릅니다.',build('tls_client','nonblock wrong.example')+'\necho "exit=$?"','handshake SSL_get_error=1 및 검증 오류, exit=1')],
 ('SSL_write_ex가 WANT_READ이면 무엇을 기다리나요?',['읽기 준비 후 같은 write 재시도','쓰기 준비만 기다림','offset 증가 후 다음 버퍼 전송'],0,'TLS 프로토콜 진행에 필요한 방향은 호출 이름과 다를 수 있습니다.'),['man3/SSL_get_error/','man3/SSL_write/','man7/ossl-guide-tls-client-non-block/'],'tls_client','WANT 후 offset이 유지되는 위치와 deadline 계산을 코드에서 찾아 설명하세요. read 버퍼 크기를 줄여도 정상 종료가 유지되는지 확인하세요.')

add('code-asio',4,'Boost.Asio와 OpenSSL의 경계',50,
 '원시 OpenSSL 호출을 이해한 뒤 Asio가 담당하는 재시도와 애플리케이션이 여전히 책임지는 설정·수명·검증을 구분합니다.',
 ['ssl::stream은 OpenSSL 연결을 감싸고 비동기 transport와 TLS 진행을 연결합니다. API 반환값 대신 completion handler의 error_code를 읽습니다.',
  'native_handle은 빌린 SSL*입니다. SSL_free하거나 Asio 작업과 별도로 SSL_read/SSL_write를 동시에 진행하지 않습니다.',
  '요청 문자열과 read 버퍼는 비동기 작업 완료까지 살아 있어야 합니다. 이 예제는 io.run이 끝날 때까지 지역 객체를 유지합니다.'],
 [section('누가 무엇을 관리하는가','ssl::context가 공통 TLS 설정을, ssl::stream이 연결과 transport를 관리합니다. native_handle을 통해 SNI와 호스트 이름을 설정하지만 실제 데이터 I/O는 Asio로 일관되게 진행합니다.',
  'verify_peer와 CA 로딩은 체인 검증의 기반입니다. SSL_set1_host가 이름 검증을 설정합니다. 사용자 verify callback에서 무조건 true를 반환하는 식으로 실패를 무시하지 않습니다.'),
  section('콜백과 버퍼 수명','async_write는 요청 바이트를 다 쓰는 composed operation입니다. request 문자열은 콜백 완료 전에 변경되지 않습니다. async_read_some은 매번 일부 바이트를 전달하므로 누적하고 다음 read를 시작합니다.',
  '타이머가 만료되면 소켓을 닫아 pending 작업을 취소하고 finished로 후속 콜백 처리를 막습니다. 이 예제는 io_context를 한 스레드에서 돌립니다. 여러 스레드가 실행하는 경우 stream 접근과 상태를 strand 등으로 직렬화해야 합니다.'),
  section('오류를 숨기지 않기','정상 TLS 종료는 eof 처리 뒤 shutdown을 완료합니다. stream_truncated 같은 오류를 일괄적으로 성공 처리하지 않습니다. 어떤 종료를 허용할지는 상위 프로토콜의 메시지 완전성 규칙과 연결해서 판단해야 합니다.','Asio가 OpenSSL 오류 큐를 이미 다뤘을 수 있습니다. 애플리케이션은 먼저 handler의 error_code를 진단하고 원시 SSL_get_error를 다른 시점의 임의 반환값으로 호출하지 않습니다.')],
 [api('ssl::stream::native_handle()','현재 stream이 관리하는 SSL* 접근.','borrowed. stream보다 오래 보관하거나 직접 SSL_free하지 않습니다.','native SSL* 핸들.','핸들로 동시 I/O를 시작해 Asio 내부 상태 진행과 경쟁시키지 않습니다.'),
  api('async_handshake / async_read_some / async_write','완료 핸들러에서 error_code 및 처리 길이 확인.','버퍼 메모리는 완료까지 유지. handler 캡처 객체도 수명 보장.','시작 함수의 반환은 완료를 의미하지 않습니다.','예외와 비동기 error_code 경로를 모두 처리합니다. 이 예제는 한 스레드에서 직렬 진행합니다.')],
 [step('Asio 정상 연결','컴파일에는 Boost 헤더와 -pthread가 필요하며 study-build가 설정합니다.',build('asio_client'),'ASIO VERIFIED; close_notify; HTTP/1.0 200 ok'),
  step('이름 검증 실패','OpenSSL 설정이 Asio 연결에도 적용됩니다.',build('asio_client','wrong.example')+'\necho "exit=$?"','handshake: certificate verify failed, exit=1')],
 ('stream.native_handle()을 owning unique_ptr<SSL>에 넣어도 되나요?',['아니요, stream이 소유합니다','예'],0,'Asio가 해제할 SSL을 다시 소유하면 이중 해제가 발생할 수 있습니다.'),['https://www.boost.org/doc/libs/latest/doc/html/boost_asio/reference/ssl__stream.html','https://www.boost.org/doc/libs/latest/doc/html/boost_asio/reference/ssl__stream/native_handle.html'],'asio_client','request가 async_write 시작 직후 파괴되는 구조라면 무엇이 잘못되는지 설명하고 소유 객체를 설계해 보세요.')

def extend(lessons):
    from enrichment import enrich
    enrich(lessons)
    lessons.extend(NEW)
    order=['basic-bytes','basic-hash','basic-random','basic-mac','basic-kdf','basic-aead','basic-kex',
      'tls-1','tls-2','tls-3','tls-record','tls-shutdown','x509-1','x509-2','x509-3','x509-chain','x509-api',
      'arch-1','arch-2','arch-3','arch-ownership','arch-bio','arch-errors','code-1','code-2','code-3','code-nonblock','code-asio']
    lessons.sort(key=lambda l:order.index(l['id']))
